		this.type = type;
		this.timeTrackingRegionId = -1;
		this.varbitId = -1;
		this.timeTrackingKey = timeTrackingKey;
		this.patchPoint = patchPoint;
		this.navigationPoint = navigationPoint;
		this.accessPoint = null;
		this.interiorRegionId = -1;
		this.accessInstruction = null;
	}

	FarmPatch(
		String displayName,
		PatchType type,
		int timeTrackingRegionId,
		int varbitId,
		WorldPoint patchPoint,
		WorldPoint accessPoint,
		int interiorRegionId,
		String accessInstruction)
	{
		this(displayName, type, timeTrackingRegionId, varbitId, patchPoint, patchPoint,
			accessPoint, interiorRegionId, accessInstruction);
	}

	FarmPatch(
		String displayName,
		PatchType type,
		int timeTrackingRegionId,
		int varbitId,
		WorldPoint patchPoint,
		WorldPoint navigationPoint,
		WorldPoint accessPoint,
		int interiorRegionId,
		String accessInstruction)
	{
		this.displayName = displayName;
		this.type = type;
		this.timeTrackingRegionId = timeTrackingRegionId;
		this.varbitId = varbitId;
		this.timeTrackingKey = timeTrackingRegionId + "." + varbitId;
		this.patchPoint = patchPoint;
		this.navigationPoint = navigationPoint;
		this.accessPoint = accessPoint;
		this.interiorRegionId = interiorRegionId;
		this.accessInstruction = accessInstruction;
	}

	String getDisplayName()
	{
		return displayName;
	}

	PatchType getType()
	{
		return type;
	}

	String getTimeTrackingKey()
	{
		return timeTrackingKey;
	}

	int getTimeTrackingRegionId()
	{
		return timeTrackingRegionId;
	}

	int getVarbitId()
	{
		return varbitId;
	}

	boolean supportsCompostReminder()
	{
		return type.supportsCompostReminder();
	}

	boolean matchesSceneObject(int objectVarbitId, WorldPoint objectLocation)
	{
		if (varbitId < 0 || varbitId != objectVarbitId || objectLocation == null)
		{
			return false;
		}

		return patchPoint.getRegionID() == objectLocation.getRegionID();
	}

	WorldPoint getNavigationTarget(WorldPoint playerLocation)
	{
		if (accessPoint != null && (playerLocation == null || playerLocation.getRegionID() != interiorRegionId))
		{
			return accessPoint;
		}
		return navigationPoint;
	}

	String getAccessInstruction(WorldPoint playerLocation)
	{
		if (accessPoint != null && (playerLocation == null || playerLocation.getRegionID() != interiorRegionId))
		{
			return accessInstruction;
		}
		return null;
	}

	private static String birdHouseKey(int varpId)
	{
		return "birdhouse." + varpId;
	}
}

package com.farmrunhelper;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/** Resolves the selected guide plan into one crop for each Farming Guild patch. */
final class FarmingContractPreplant
{
	static final String DEVELOPMENT_PROPERTY = "freyjas.flora.farmingContracts";
	private static final Crop IRIT = tracked("Irit", FarmingGuildContractPatch.HERB, FarmPatch.FARMING_GUILD, ItemID.UNIDENTIFIED_IRIT);
	private static final Crop CADANTINE = tracked("Cadantine", FarmingGuildContractPatch.HERB, FarmPatch.FARMING_GUILD, ItemID.UNIDENTIFIED_CADANTINE);
	private static final Crop LANTADYME = tracked("Lantadyme", FarmingGuildContractPatch.HERB, FarmPatch.FARMING_GUILD, ItemID.UNIDENTIFIED_LANTADYME);
	private static final Crop SNAPDRAGON = tracked("Snapdragon", FarmingGuildContractPatch.HERB, FarmPatch.FARMING_GUILD, ItemID.UNIDENTIFIED_SNAPDRAGON);
	private static final Crop MAPLE = tracked("Maple tree", FarmingGuildContractPatch.TREE, FarmPatch.TREE_FARMING_GUILD, ItemID.MAPLE_LOGS);
	private static final Crop YEW = tracked("Yew tree", FarmingGuildContractPatch.TREE, FarmPatch.TREE_FARMING_GUILD, ItemID.YEW_LOGS);
	private static final Crop PALM = tracked("Palm tree", FarmingGuildContractPatch.FRUIT_TREE, FarmPatch.FRUIT_TREE_FARMING_GUILD, ItemID.COCONUT);
	private static final Crop WHITEBERRIES = raw("Whiteberries", FarmingGuildContractPatch.BUSH, ItemID.WHITE_BERRIES);
	private static final Crop JANGERBERRIES = raw("Jangerberries", FarmingGuildContractPatch.BUSH, ItemID.JANGERBERRIES);
	private static final Crop POISON_IVY = raw("Poison ivy", FarmingGuildContractPatch.BUSH, ItemID.POISONIVY_BERRIES);
	private static final Crop CACTUS = raw("Cactus", FarmingGuildContractPatch.CACTUS, ItemID.CACTUS_SPINE);
	private static final Crop POTATO_CACTUS = raw("Potato cactus", FarmingGuildContractPatch.CACTUS, ItemID.CACTUS_POTATO);
	private static final Crop WHITE_LILY = raw("White lily", FarmingGuildContractPatch.FLOWER, ItemID.WHITELILLY);
	private static final Crop WATERMELON = raw("Watermelon", FarmingGuildContractPatch.ALLOTMENT_NORTH, ItemID.WATERMELON);
	private static final Crop STRAWBERRIES = raw("Strawberries", FarmingGuildContractPatch.ALLOTMENT_SOUTH, ItemID.STRAWBERRY);
	private static final Crop SNAPE_GRASS = raw("Snape grass", FarmingGuildContractPatch.ALLOTMENT_SOUTH, ItemID.SNAPE_GRASS);

	private FarmingContractPreplant()
	{
	}

	static boolean isDevelopmentEnabled()
	{
		return Boolean.getBoolean(DEVELOPMENT_PROPERTY);
	}

	static List<Crop> crops(FarmRunHelperConfig config)
	{
		if (config.farmingContractTier() == FarmingContractTier.MEDIUM)
		{
			return Arrays.asList(
				IRIT,
				MAPLE,
				mediumBush(config.mediumContractBush()),
				CACTUS,
				WHITE_LILY,
				WATERMELON,
				STRAWBERRIES);
		}

		return Arrays.asList(
			hardHerb(config.hardContractHerb()),
			hardTree(config.hardContractTree()),
			PALM,
			hardBush(config.hardContractBush()),
			POTATO_CACTUS,
			WHITE_LILY,
			WATERMELON,
			SNAPE_GRASS);
	}

	private static Crop hardHerb(FarmingContractOptions.HardHerb herb)
	{
		switch (herb)
		{
			case LANTADYME: return LANTADYME;
			case SNAPDRAGON: return SNAPDRAGON;
			case CADANTINE:
			default: return CADANTINE;
		}
	}

	private static Crop hardTree(FarmingContractOptions.HardTree tree)
	{
		return tree == FarmingContractOptions.HardTree.YEW ? YEW : MAPLE;
	}

	private static Crop hardBush(FarmingContractOptions.HardBush bush)
	{
		return bush == FarmingContractOptions.HardBush.WHITEBERRIES ? WHITEBERRIES : POISON_IVY;
	}

	private static Crop mediumBush(FarmingContractOptions.MediumBush bush)
	{
		return bush == FarmingContractOptions.MediumBush.JANGERBERRIES ? JANGERBERRIES : WHITEBERRIES;
	}

	private static Crop tracked(String name, FarmingGuildContractPatch patch, FarmPatch trackedPatch, int itemId)
	{
		return new Crop(name, patch, trackedPatch, itemId);
	}

	private static Crop raw(String name, FarmingGuildContractPatch patch, int itemId)
	{
		return new Crop(name, patch, null, itemId);
	}

	static final class Crop
	{
		private final String displayName;
		private final FarmingGuildContractPatch patch;
		private final FarmPatch trackedPatch;
		private final int itemId;

		private Crop(String displayName, FarmingGuildContractPatch patch, FarmPatch trackedPatch, int itemId)
		{
			this.displayName = displayName;
			this.patch = patch;
			this.trackedPatch = trackedPatch;
			this.itemId = itemId;
		}

		String getDisplayName()
		{
			return displayName;
		}

		FarmingGuildContractPatch getPatch()
		{
			return patch;
		}

		int getItemId()
		{
			return itemId;
		}

		boolean isAllotment()
		{
			return patch == FarmingGuildContractPatch.ALLOTMENT_NORTH
				|| patch == FarmingGuildContractPatch.ALLOTMENT_SOUTH;
		}

		boolean needsPreplant(TimeTrackingService timeTrackingService, long now)
		{
			if (trackedPatch != null)
			{
				PatchPrediction prediction = timeTrackingService.predict(trackedPatch);
				return prediction.getEffectiveState(now) == PatchState.EMPTY;
			}

			Integer observedValue = timeTrackingService.getObservedVarbitValue(patch);
			return observedValue == null || patch.isEmptyValue(observedValue);
		}
	}
}

package com.farmrunhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class SeedInventory
{
	enum Location
	{
		INVENTORY("Inventory"),
		BANK("Bank"),
		SEED_VAULT("Seed Vault");

		private final String displayName;

		Location(String displayName)
		{
			this.displayName = displayName;
		}

		String getDisplayName()
		{
			return displayName;
		}
	}

	static final class ItemCount
	{
		private final String name;
		private final long quantity;

		private ItemCount(String name, long quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}

		String getName()
		{
			return name;
		}

		long getQuantity()
		{
			return quantity;
		}
	}

	static final class Builder
	{
		private final EnumMap<Location, EnumMap<PatchType, Long>> allCounts = new EnumMap<>(Location.class);
		private final EnumMap<Location, EnumMap<PatchType, Long>> plantableCounts = new EnumMap<>(Location.class);
		private final EnumMap<Location, Map<String, Long>> items = new EnumMap<>(Location.class);
		private final EnumMap<Location, Long> updatedAt = new EnumMap<>(Location.class);

		private Builder()
		{
			for (Location location : Location.values())
			{
				allCounts.put(location, new EnumMap<>(PatchType.class));
				plantableCounts.put(location, new EnumMap<>(PatchType.class));
				items.put(location, new LinkedHashMap<>());
				updatedAt.put(location, -1L);
			}
		}

		Builder markObserved(Location location, long updatedAtMs)
		{
			updatedAt.put(location, updatedAtMs);
			return this;
		}

		Builder add(
			Location location,
			PatchType patchType,
			boolean directlyPlantable,
			String name,
			long quantity)
		{
			if (quantity <= 0L)
			{
				return this;
			}

			items.get(location).merge(name, quantity, Long::sum);
			if (patchType != null)
			{
				allCounts.get(location).merge(patchType, quantity, Long::sum);
				if (directlyPlantable)
				{
					plantableCounts.get(location).merge(patchType, quantity, Long::sum);
				}
			}
			return this;
		}

		private Builder addPlantableTotal(PatchType patchType, long quantity)
		{
			if (quantity > 0L)
			{
				allCounts.get(Location.INVENTORY).put(patchType, quantity);
				plantableCounts.get(Location.INVENTORY).put(patchType, quantity);
			}
			return this;
		}

		SeedInventory build()
		{
			return new SeedInventory(this);
		}
	}

	private final EnumMap<Location, EnumMap<PatchType, Long>> allCounts;
	private final EnumMap<Location, EnumMap<PatchType, Long>> plantableCounts;
	private final EnumMap<Location, List<ItemCount>> items;
	private final EnumMap<Location, Long> updatedAt;

	SeedInventory(
		int herbSeeds,
		int treeSaplings,
		int fruitTreeSaplings,
		int hardwoodSaplings,
		int calquatSaplings,
		int seaweedSpores)
	{
		this(legacyBuilder(
			herbSeeds,
			treeSaplings,
			fruitTreeSaplings,
			hardwoodSaplings,
			calquatSaplings,
			seaweedSpores));
	}

	private SeedInventory(Builder builder)
	{
		allCounts = copyCounts(builder.allCounts);
		plantableCounts = copyCounts(builder.plantableCounts);
		items = new EnumMap<>(Location.class);
		updatedAt = new EnumMap<>(builder.updatedAt);

		for (Location location : Location.values())
		{
			List<ItemCount> locationItems = new ArrayList<>();
			for (Map.Entry<String, Long> entry : builder.items.get(location).entrySet())
			{
				locationItems.add(new ItemCount(entry.getKey(), entry.getValue()));
			}
			locationItems.sort(Comparator.comparing(ItemCount::getName, String.CASE_INSENSITIVE_ORDER));
			items.put(location, Collections.unmodifiableList(locationItems));
		}
	}

	private static EnumMap<Location, EnumMap<PatchType, Long>> copyCounts(
		EnumMap<Location, EnumMap<PatchType, Long>> source)
	{
		EnumMap<Location, EnumMap<PatchType, Long>> copy = new EnumMap<>(Location.class);
		for (Location location : Location.values())
		{
			copy.put(location, new EnumMap<>(source.get(location)));
		}
		return copy;
	}

	private static Builder legacyBuilder(
		int herbSeeds,
		int treeSaplings,
		int fruitTreeSaplings,
		int hardwoodSaplings,
		int calquatSaplings,
		int seaweedSpores)
	{
		return builder()
			.markObserved(Location.INVENTORY, 0L)
			.addPlantableTotal(PatchType.HERB, herbSeeds)
			.addPlantableTotal(PatchType.TREE, treeSaplings)
			.addPlantableTotal(PatchType.FRUIT_TREE, fruitTreeSaplings)
			.addPlantableTotal(PatchType.HARDWOOD_TREE, hardwoodSaplings)
			.addPlantableTotal(PatchType.CALQUAT, calquatSaplings)
			.addPlantableTotal(PatchType.SEAWEED, seaweedSpores);
	}

	static Builder builder()
	{
		return new Builder();
	}

	static SeedInventory empty()
	{
		return builder().markObserved(Location.INVENTORY, 0L).build();
	}

	boolean canPlant(PatchType type)
	{
		if (!requiresPlantingItem(type))
		{
			return true;
		}
		return getPlantableCount(Location.INVENTORY, type) > 0L;
	}

	String getStoredPlantingLocations(PatchType type)
	{
		boolean bank = getPlantableCount(Location.BANK, type) > 0L;
		boolean vault = getPlantableCount(Location.SEED_VAULT, type) > 0L;
		if (bank && vault)
		{
			return "Bank / Seed Vault";
		}
		if (bank)
		{
			return "Bank";
		}
		return vault ? "Seed Vault" : null;
	}

	boolean hasSeedToPrepare(PatchType type)
	{
		long total = 0L;
		long plantable = 0L;
		for (Location location : Location.values())
		{
			total += getCount(allCounts, location, type);
			plantable += getPlantableCount(location, type);
		}
		return total > plantable;
	}

	boolean hasUnknownStoredStock()
	{
		return !isObserved(Location.BANK) || !isObserved(Location.SEED_VAULT);
	}

	boolean isObserved(Location location)
	{
		return updatedAt.get(location) >= 0L;
	}

	long getUpdatedAt(Location location)
	{
		return updatedAt.get(location);
	}

	List<ItemCount> getItems(Location location)
	{
		return items.get(location);
	}

	long getTotal(Location location)
	{
		long total = 0L;
		for (ItemCount item : items.get(location))
		{
			total += item.getQuantity();
		}
		return total;
	}

	private long getPlantableCount(Location location, PatchType type)
	{
		return getCount(plantableCounts, location, type);
	}

	private static long getCount(
		EnumMap<Location, EnumMap<PatchType, Long>> counts,
		Location location,
		PatchType type)
	{
		Long value = counts.get(location).get(type);
		return value == null ? 0L : value;
	}

	private static boolean requiresPlantingItem(PatchType type)
	{
		switch (type)
		{
			case HERB:
			case HOPS:
			case TREE:
			case FRUIT_TREE:
			case HARDWOOD_TREE:
			case CALQUAT:
			case SEAWEED:
				return true;
			default:
				return false;
		}
	}

}

