	private static final class PatchRowPanel extends JPanel
	{
		private final float contentOpacity;

		private PatchRowPanel(float contentOpacity)
		{
			this.contentOpacity = contentOpacity;
		}

		@Override
		public void paint(Graphics graphics)
		{
			if (contentOpacity >= 1.0f || getWidth() <= 0 || getHeight() <= 0)
			{
				super.paint(graphics);
				return;
			}

			BufferedImage image = new BufferedImage(getWidth(), getHeight(), BufferedImage.TYPE_INT_ARGB);
			Graphics2D imageGraphics = image.createGraphics();
			super.paint(imageGraphics);
			imageGraphics.dispose();

			Graphics2D graphics2D = (Graphics2D) graphics.create();
			graphics2D.setComposite(AlphaComposite.SrcOver.derive(contentOpacity));
			graphics2D.drawImage(image, 0, 0, null);
			graphics2D.dispose();
		}
	}

	private JLayeredPane patchIcon(PatchSnapshot snapshot)
	{
		JLayeredPane layeredIcon = new JLayeredPane();
		layeredIcon.setPreferredSize(new Dimension(CROP_ICON_WIDTH, CROP_ICON_HEIGHT));
		String tooltip = cropIconTooltip(snapshot);
		layeredIcon.setToolTipText(tooltip);

		JLabel cropIcon = new JLabel("", SwingConstants.CENTER);
		cropIcon.setBounds(0, 0, CROP_ICON_WIDTH, CROP_ICON_HEIGHT);
		cropIcon.setToolTipText(tooltip);
		int cropItemId = PatchCropIcon.itemIdFor(
			snapshot.getPatch().getType(),
			snapshot.getPrediction().getCropName());
		bindItemIcon(
			cropIcon,
			cropItemId,
			CROP_ICON_WIDTH,
			CROP_ICON_HEIGHT,
			cropIcons);
		layeredIcon.add(cropIcon, (Object) 0);

		CompostState compostState = snapshot.getCompostState();
		if (compostState != null)
		{
			JLabel compostIcon = new JLabel("", SwingConstants.CENTER);
			compostIcon.setBounds(
				CROP_ICON_WIDTH - COMPOST_ICON_WIDTH,
				CROP_ICON_HEIGHT - COMPOST_ICON_HEIGHT,
				COMPOST_ICON_WIDTH,
				COMPOST_ICON_HEIGHT);
			compostIcon.setToolTipText(tooltip);
			bindItemIcon(
				compostIcon,
				compostState.getItemId(),
				COMPOST_ICON_WIDTH,
				COMPOST_ICON_HEIGHT,
				compostIcons);
			layeredIcon.add(compostIcon, (Object) 1);
		}

		return layeredIcon;
	}

	private void bindItemIcon(
		JLabel label,
		int itemId,
		int maximumWidth,
		int maximumHeight,
		Map<Integer, ImageIcon> cache)
	{
		if (itemManager == null)
		{
			return;
		}

		ImageIcon cached = cache.get(itemId);
		if (cached != null)
		{
			label.setIcon(cached);
			return;
		}

		AsyncBufferedImage source = itemManager.getImage(itemId);
		if (source == null)
		{
			return;
		}

		source.onLoaded(() ->
		{
			ImageIcon icon = scaledItemIcon(source, maximumWidth, maximumHeight);
			SwingUtilities.invokeLater(() ->
			{
				ImageIcon resolved = cache.computeIfAbsent(itemId, ignored -> icon);
				label.setIcon(resolved);
				label.revalidate();
				label.repaint();
			});
		});
	}

	private static ImageIcon scaledItemIcon(BufferedImage source, int maximumWidth, int maximumHeight)
	{
		double scale = Math.min(
			(double) maximumWidth / source.getWidth(),
			(double) maximumHeight / source.getHeight());
		int width = Math.max(1, (int) Math.round(source.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(source.getHeight() * scale));
		return new ImageIcon(ImageUtil.resizeImage(source, width, height));
	}

	private static String cropIconTooltip(PatchSnapshot snapshot)
	{
		String cropName = snapshot.getPrediction().getCropName();
		String cropDescription;
		if ("Empty".equals(cropName) || "Unknown".equals(cropName) || "Herb".equals(cropName))
		{
			cropDescription = snapshot.getPatch().getType().getDisplayName();
		}
		else
		{
			cropDescription = cropName;
		}

		CompostState compostState = snapshot.getCompostState();
		return compostState == null
			? cropDescription
			: cropDescription + " with " + compostName(compostState);
	}

	private static String compostName(CompostState compostState)
	{
		switch (compostState)
		{
			case ULTRACOMPOST:
				return "ultracompost";
			case SUPERCOMPOST:
				return "supercompost";
			default:
				return "compost";
		}
	}

	private static String statusText(
		FarmPatch patch,
		PatchPrediction prediction,
		PatchState state,
		long now,
		SeedInventory seedInventory)
	{
		switch (state)
		{
			case READY:
				return prediction.getCropName();
			case GROWING:
				return prediction.getCropName() + " · " + formatRemaining(prediction.getReadyAt() - now);
			case DISEASED:
				return prediction.getCropName() + " · Diseased";
			case DEAD:
				return prediction.getCropName() + " · Dead";
			case EMPTY:
				return patch.getType() == PatchType.BIRD_HOUSE && !"Empty".equals(prediction.getCropName())
					? prediction.getCropName() + " · Needs seed"
					: "Empty";
			default:
				return "Visit once to sync";
		}
	}

	private static String formatRemaining(long seconds)
	{
		if (seconds <= 0)
		{
			return "Ready";
		}
		Duration duration = Duration.ofSeconds(seconds);
		long hours = duration.toHours();
		long minutes = duration.minusHours(hours).toMinutes();
		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		return Math.max(1, minutes) + "m";
	}

	private static String stateLabel(PatchState state)
	{
		switch (state)
		{
			case READY:
				return "Ready";
			case GROWING:
				return "Growing";
			case DISEASED:
				return "Diseased";
			case DEAD:
				return "Dead";
			case EMPTY:
				return "Empty";
			default:
				return "Unknown";
		}
	}

	private static Color statusColor(PatchState state)
	{
		switch (state)
		{
			case READY:
				return PatchMasterTheme.READY;
			case GROWING:
				return PatchMasterTheme.GROWING;
			case DISEASED:
				return PatchMasterTheme.DISEASED;
			case DEAD:
				return PatchMasterTheme.DEAD;
			case EMPTY:
				return PatchMasterTheme.EMPTY;
			default:
				return PatchMasterTheme.UNKNOWN;
		}
	}

	private static String wrap(String text)
	{
		return wrap(text, 195);
	}

	private static String wrap(String text, int width)
	{
		int maxCharactersPerLine = Math.max(12, width / 7);
		StringBuilder wrapped = new StringBuilder();
		int lineLength = 0;
		for (String word : text.split("\\s+"))
		{
			if (lineLength > 0 && lineLength + 1 + word.length() > maxCharactersPerLine)
			{
				wrapped.append("<br>");
				lineLength = 0;
			}
			else if (lineLength > 0)
			{
				wrapped.append(' ');
				lineLength++;
			}
			wrapped.append(escapeHtml(word));
			lineLength += word.length();
		}
		return "<html><body>" + wrapped + "</body></html>";
	}

	private static String escapeHtml(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.farmrunhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

final class PatchTypeOrder
{
	private static final List<PatchType> DEFAULT_ORDER;
	static final String DEFAULT_SERIALIZED;

	static
	{
		List<PatchType> defaultOrder = new ArrayList<>();
		Collections.addAll(defaultOrder, PatchType.values());
		DEFAULT_ORDER = Collections.unmodifiableList(defaultOrder);
		DEFAULT_SERIALIZED = serialize(DEFAULT_ORDER);
	}

	private PatchTypeOrder()
	{
	}

	static List<PatchType> parse(String serialized)
	{
		List<PatchType> parsed = new ArrayList<>();
		if (serialized != null)
		{
			for (String token : serialized.split(","))
			{
				try
				{
					parsed.add(PatchType.valueOf(token.trim().toUpperCase(Locale.ROOT)));
				}
				catch (IllegalArgumentException ignored)
				{
					// Ignore retired or malformed values and append missing types below.
				}
			}
		}
		return normalize(parsed);
	}

	static String serialize(List<PatchType> order)
	{
		StringBuilder serialized = new StringBuilder();
		for (PatchType type : normalize(order))
		{
			if (serialized.length() > 0)
			{
				serialized.append(',');
			}
			serialized.append(type.name());
		}
		return serialized.toString();
	}

	static List<FarmPatch> orderedPatches(String serialized)
	{
		List<FarmPatch> patches = new ArrayList<>();
		for (PatchType type : parse(serialized))
		{
			for (FarmPatch patch : FarmPatch.values())
			{
				if (patch.getType() == type)
				{
					patches.add(patch);
				}
			}
		}
		return patches;
	}

	static List<FarmPatch> orderedEnabledPatches(String serialized, FarmRunHelperConfig config)
	{
		List<FarmPatch> patches = new ArrayList<>();
		for (FarmPatch patch : orderedPatches(serialized))
		{
			if (PatchSelection.isEnabled(config, patch))
			{
				patches.add(patch);
			}
		}
		return patches;
	}

	private static List<PatchType> normalize(List<PatchType> order)
	{
		List<PatchType> normalized = new ArrayList<>();
		Set<PatchType> seen = EnumSet.noneOf(PatchType.class);
		if (order != null)
		{
			for (PatchType type : order)
			{
				if (type != null && seen.add(type))
				{
					normalized.add(type);
				}
			}
		}

		for (PatchType type : DEFAULT_ORDER)
		{
			if (seen.add(type))
			{
				normalized.add(type);
			}
		}
		return normalized;
	}
}

package com.farmrunhelper;

final class FarmingClock
{
	private FarmingClock()
	{
	}

	static long readyAt(
		int tickRateMinutes,
		int stage,
		int stages,
		long observedAt,
		Integer offsetPrecisionMinutes,
		Integer offsetMinutes)
	{
		if (tickRateMinutes <= 0 || observedAt <= 0 || stage >= stages - 1)
		{
			return 0;
		}

		long observedTick = tickTime(
			tickRateMinutes,
			0,
			observedAt,
			offsetPrecisionMinutes,
			offsetMinutes);

		return tickTime(
			tickRateMinutes,
			stages - 1 - stage,
			observedTick,
			offsetPrecisionMinutes,
			offsetMinutes);
	}

	static long tickTime(
		int tickRateMinutes,
		int ticks,
		long requestedTime,
		Integer offsetPrecisionMinutes,
		Integer offsetMinutes)
	{
		long offsetSeconds = 0;
		if (offsetPrecisionMinutes != null && offsetMinutes != null
			&& (offsetPrecisionMinutes >= tickRateMinutes || offsetPrecisionMinutes >= 40))
		{
			offsetSeconds = Math.floorMod(offsetMinutes, tickRateMinutes) * 60L;
		}

		long adjustedTime = requestedTime + offsetSeconds;
		long tickSeconds = tickRateMinutes * 60L;
		long currentTick = adjustedTime - Math.floorMod(adjustedTime, tickSeconds);
		return currentTick + ticks * tickSeconds - offsetSeconds;
	}
}

