import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Freyja's Flora",
	description = "Tracks farming patches and birdhouses and sends visual destinations to Shortest Path",
	tags = {"farming", "herb", "hops", "tree", "fruit", "hardwood", "calquat", "coral", "seaweed", "birdhouse", "hunter", "timer", "route", "path"}
)
@PluginDependency(TimeTrackingPlugin.class)
public class FarmRunHelperPlugin extends Plugin implements FarmRunHelperPanel.Listener
{
	private static final int PANEL_REFRESH_INTERVAL_MS = 30_000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private FarmRunHelperConfig config;

	@Inject
	private FarmRunHelperPanel panel;

	@Inject
	private TimeTrackingService timeTrackingService;

	@Inject
	private ShortestPathService shortestPathService;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CompostReminderOverlay compostReminderOverlay;

	@Inject
	private SeedInventoryService seedInventoryService;

	private final RunPlanner runPlanner = new RunPlanner();
	private final FarmRunProgress runProgress = new FarmRunProgress();
	private NavigationButton navigationButton;
	private FarmPatch currentPatch;
	private PatchState currentPatchState;
	private boolean currentPatchReplanted;
	private WorldPoint lastNavigationTarget;
	private boolean runActive;
	private Timer panelRefreshTimer;

	@Provides
	FarmRunHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FarmRunHelperConfig.class);
	}

	@Override
	protected void startUp()
	{
		seedInventoryService.resetProfile();
		normalizePatchTypeOrderConfiguration();
		panel.setListener(this);
		addNavigation(FarmRunIcon.fallback());
		FarmRunIcon.loadFarmersShirt(itemManager, 16, icon -> SwingUtilities.invokeLater(() ->
		{
			if (navigationButton != null)
			{
				clientToolbar.removeNavigation(navigationButton);
				addNavigation(icon);
				clientToolbar.addNavigation(navigationButton);
			}
		}));
		clientToolbar.addNavigation(navigationButton);
		overlayManager.add(compostReminderOverlay);
		panelRefreshTimer = new Timer(PANEL_REFRESH_INTERVAL_MS, event ->
			clientThread.invokeLater(() ->
			{
				if (panelRefreshTimer != null)
				{
					refreshPanel();
				}
			}));
		panelRefreshTimer.setCoalesce(true);
		panelRefreshTimer.start();
		clientThread.invokeLater(() ->
		{
			compostReminderOverlay.rebuild();
			refreshPanel();
		});
	}

	private void addNavigation(java.awt.image.BufferedImage icon)
	{
		navigationButton = NavigationButton.builder()
			.tooltip("Freyja's Flora")
			.icon(icon)
			.panel(panel)
			.priority(5)
			.build();
	}

	@Override
	protected void shutDown()
	{
		if (panelRefreshTimer != null)
		{
			panelRefreshTimer.stop();
			panelRefreshTimer = null;
		}
		if (config.clearPathOnShutdown() && lastNavigationTarget != null)
		{
			shortestPathService.clear();
		}
		currentPatch = null;
		currentPatchState = null;
		currentPatchReplanted = false;
		lastNavigationTarget = null;
		runProgress.clear();
		runActive = false;
		overlayManager.remove(compostReminderOverlay);
		compostReminderOverlay.clear();
		panel.setListener(null);
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		seedInventoryService.updateOpenStorages();
		updateInteriorRoute();
		checkForCompletedPatch();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (FarmRunHelperConfig.GROUP.equals(event.getGroup())
			&& FarmRunHelperConfig.PATCH_TYPE_ORDER_KEY.equals(event.getKey()))
		{
			normalizePatchTypeOrderConfiguration();
		}

		if (FarmRunHelperConfig.GROUP.equals(event.getGroup())
			|| TimeTrackingConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(this::refreshPanel);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		seedInventoryService.resetProfile();
		currentPatch = null;
		currentPatchState = null;
		currentPatchReplanted = false;
		lastNavigationTarget = null;
		runProgress.clear();
		runActive = false;
		normalizePatchTypeOrderConfiguration();
		refreshPanel();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			compostReminderOverlay.clear();
		}
		if (event.getGameState() == GameState.LOGGED_IN || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			if (event.getGameState() == GameState.LOGGED_IN)
			{
				compostReminderOverlay.rebuild();
			}
			refreshPanel();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		compostReminderOverlay.track(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		compostReminderOverlay.untrack(event.getGameObject());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId() > 0x8000
			? event.getContainerId() - 0x8000
			: event.getContainerId();
		if (containerId == InventoryID.BANK || containerId == InventoryID.SEED_VAULT)
		{
			seedInventoryService.onItemContainerChanged(event);
		}
		if (containerId == InventoryID.INV
			|| containerId == InventoryID.BANK
			|| containerId == InventoryID.SEED_VAULT)
		{
			clientThread.invokeLater(this::refreshPanel);
		}
	}

	@Override
	public void onStartRun()
	{
		clientThread.invokeLater(() ->
		{
			runActive = true;
			runProgress.start(getActionableSnapshots());
			routeCurrentPatch();
		});
	}

	@Override
	public void onNextPatch()
	{
		clientThread.invokeLater(() ->
		{
			runActive = true;
			runProgress.advance(getActionableSnapshots());
			routeCurrentPatch();
		});
	}

	@Override
	public void onClearRoute()
	{
		clientThread.invokeLater(() ->
		{
			shortestPathService.clear();
			currentPatch = null;
			currentPatchState = null;
			currentPatchReplanted = false;
			lastNavigationTarget = null;
			runProgress.clear();
			runActive = false;
			refreshPanel();
		});
	}

	@Override
	public void onDoneToggled(FarmPatch patch)
	{
		clientThread.invokeLater(() ->
		{
			if (!runProgress.toggleDone(patch, getActionableSnapshots()))
			{
				return;
			}
			runActive = true;
			if (currentPatch == null)
			{
				routeCurrentPatch();
			}
			else
			{
				refreshPanel();
			}
		});
	}

	@Override
	public void onRouteTo(FarmPatch patch)
	{
		clientThread.invokeLater(() ->
		{
			runActive = false;
			routeToPatch(patch);
		});
	}

	@Override
	public void onPatchTypeOrderChanged(List<PatchType> order)
	{
		configManager.setConfiguration(
			FarmRunHelperConfig.GROUP,
			FarmRunHelperConfig.PATCH_TYPE_ORDER_KEY,
			PatchTypeOrder.serialize(order));
	}

	private void routeNextPatch()
	{
		runProgress.advance(getActionableSnapshots());
		routeCurrentPatch();
	}

	private void routeCurrentPatch()
	{
		FarmPatch nextPatch = runProgress.getCurrentPatch();
		if (nextPatch == null)
		{
			currentPatch = null;
			currentPatchState = null;
			currentPatchReplanted = false;
			runActive = false;
			refreshPanel();
			return;
		}
		routeToPatch(nextPatch);
	}

	private void routeToPatch(FarmPatch patch)
	{
		runProgress.select(patch);
		currentPatch = patch;
		Player localPlayer = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || localPlayer == null)
		{
			refreshPanel();
			return;
		}

		currentPatchState = timeTrackingService.predict(patch).getEffectiveState(Instant.now().getEpochSecond());
		currentPatchReplanted = false;
		WorldPoint playerLocation = localPlayer.getWorldLocation();
		lastNavigationTarget = patch.getNavigationTarget(playerLocation);
		shortestPathService.routeTo(lastNavigationTarget);
		refreshPanel();
	}

	private void updateInteriorRoute()
	{
		if (currentPatch == null || client.getLocalPlayer() == null)
		{
			return;
		}

		WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();
		WorldPoint desiredTarget = currentPatch.getNavigationTarget(playerLocation);
		if (!desiredTarget.equals(lastNavigationTarget))
		{
			lastNavigationTarget = desiredTarget;
			shortestPathService.routeTo(desiredTarget);
		}
	}

	private void checkForCompletedPatch()
	{
		if (!runActive || !config.advanceAfterReplant() || currentPatch == null)
		{
			return;
		}

		PatchState observedState = timeTrackingService.predict(currentPatch)
			.getEffectiveState(Instant.now().getEpochSecond());
		if (currentPatchState != null && PatchCompletion.wasReplanted(currentPatchState, observedState))
		{
			currentPatchReplanted = true;
		}

		if (currentPatchReplanted && canAdvanceFromCurrentPatch())
		{
			routeNextPatch();
			return;
		}

		currentPatchState = observedState;
	}

	private boolean canAdvanceFromCurrentPatch()
	{
		return !config.waitForCompostBeforeAdvance()
			|| !currentPatch.supportsCompostReminder()
			|| timeTrackingService.hasRecordedCompost(currentPatch);
	}

	private void refreshPanel()
	{
		panel.update(
			getVisibleSnapshots(),
			PatchTypeOrder.parse(config.patchTypeOrder()),
			currentPatch,
			runProgress.getDonePatches(),
			Instant.now().getEpochSecond(),
			seedInventoryService.getInventory());
	}

	private List<PatchSnapshot> getVisibleSnapshots()
	{
		List<PatchSnapshot> snapshots = new ArrayList<>();
		for (FarmPatch patch : PatchTypeOrder.orderedEnabledPatches(config.patchTypeOrder(), config))
		{
			snapshots.add(new PatchSnapshot(
				patch,
				timeTrackingService.predict(patch),
				timeTrackingService.getRecordedCompost(patch)));
		}
		return snapshots;
	}

	private List<PatchSnapshot> getActionableSnapshots()
	{
		long now = Instant.now().getEpochSecond();
		SeedInventory seedInventory = seedInventoryService.getInventory();
		List<PatchSnapshot> actionableSnapshots = new ArrayList<>();
		for (PatchSnapshot snapshot : getVisibleSnapshots())
		{
			if (runPlanner.isActionable(
				snapshot,
				now,
				config.includeEmpty(),
				config.includeUnknown(),
				seedInventory,
				config.skipEmptyWithoutSeed()))
			{
				actionableSnapshots.add(snapshot);
			}
		}
		return actionableSnapshots;
	}

	private void normalizePatchTypeOrderConfiguration()
	{
		String currentOrder = config.patchTypeOrder();
		String normalizedOrder = PatchTypeOrder.serialize(PatchTypeOrder.parse(currentOrder));
		if (!normalizedOrder.equals(currentOrder))
		{
			configManager.setConfiguration(
				FarmRunHelperConfig.GROUP,
				FarmRunHelperConfig.PATCH_TYPE_ORDER_KEY,
				normalizedOrder);
		}
	}

}

package com.farmrunhelper;

enum PatchHighlight
{
	COMPOST,
	READY,
	EMPTY,
	DEAD,
	DISEASED;

	static PatchHighlight forPatch(FarmPatch patch, PatchState state, boolean hasRecordedCompost)
	{
		if (!patch.getType().supportsSceneHighlights())
		{
			return null;
		}

		switch (state)
		{
			case READY:
				return READY;
			case EMPTY:
				return EMPTY;
			case DEAD:
				return DEAD;
			case DISEASED:
				return DISEASED;
			case GROWING:
				return CompostReminder.shouldShow(patch, state, hasRecordedCompost) ? COMPOST : null;
			default:
				return null;
		}
	}
}

package com.farmrunhelper;

final class PatchPrediction
{
	private final String cropName;
	private final PatchState observedState;
	private final long observedAt;
	private final long readyAt;

	private PatchPrediction(String cropName, PatchState observedState, long observedAt, long readyAt)
	{
		this.cropName = cropName;
		this.observedState = observedState;
		this.observedAt = observedAt;
		this.readyAt = readyAt;
	}

	static PatchPrediction known(String cropName, PatchState state, long observedAt, long readyAt)
	{
		return new PatchPrediction(cropName, state, observedAt, readyAt);
	}

	static PatchPrediction unknown()
	{
		return new PatchPrediction("Unknown", PatchState.UNKNOWN, 0, 0);
	}

	String getCropName()
	{
		return cropName;
	}

	PatchState getObservedState()
	{
		return observedState;
	}

	long getObservedAt()
	{
		return observedAt;
	}

	long getReadyAt()
	{
		return readyAt;
	}

	PatchState getEffectiveState(long now)
	{
		if (observedState == PatchState.GROWING && readyAt > 0 && readyAt <= now)
		{
			return PatchState.READY;
		}
		return observedState;
	}
}

package com.farmrunhelper;

import java.util.EnumSet;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import net.runelite.client.plugins.timetracking.farming.CompostState;

final class TimeTrackingService
{
	static final int BIRD_HOUSE_DURATION_SECONDS = 50 * 60;

	private final Client client;
	private final ConfigManager configManager;

	@Inject
	TimeTrackingService(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	PatchPrediction predict(FarmPatch patch)
	{
		String stored = configManager.getRSProfileConfiguration(
			TimeTrackingConfig.CONFIG_GROUP,
			patch.getTimeTrackingKey());
		Optional<TimeTrackingValue> parsed = TimeTrackingValue.parse(stored);
		if (!parsed.isPresent())
		{
			return PatchPrediction.unknown();
		}

		TimeTrackingValue value = parsed.get();
		DecodedPatchState decoded = PatchStateDecoder.decode(patch.getType(), value.getVarbitValue());
		if (decoded == null)
		{
			return PatchPrediction.unknown();
		}

		int tickRate = decoded.getTickRateMinutes();
		if (tickRate > 0 && isLeaguesWorld())
		{
			tickRate = Math.max(1, tickRate / 5);
		}

		Integer offsetPrecision = configManager.getRSProfileConfiguration(
			TimeTrackingConfig.CONFIG_GROUP,
			TimeTrackingConfig.FARM_TICK_OFFSET_PRECISION,
			int.class);
		Integer offset = configManager.getRSProfileConfiguration(
			TimeTrackingConfig.CONFIG_GROUP,
			TimeTrackingConfig.FARM_TICK_OFFSET,
			int.class);

		long readyAt = 0;
		if (decoded.getState() == PatchState.GROWING)
		{
			readyAt = patch.getType() == PatchType.BIRD_HOUSE
				? birdHouseReadyAt(value.getObservedAt())
				: FarmingClock.readyAt(
					tickRate,
					decoded.getStage(),
					decoded.getStages(),
					value.getObservedAt(),
					offsetPrecision,
					offset);
		}

		return PatchPrediction.known(
			decoded.getCropName(),
			decoded.getState(),
			value.getObservedAt(),
			readyAt);
	}

	Integer getObservedVarbitValue(FarmingGuildContractPatch patch)
	{
		String stored = configManager.getRSProfileConfiguration(
			TimeTrackingConfig.CONFIG_GROUP,
			patch.getTimeTrackingKey());
		return TimeTrackingValue.parse(stored)
			.map(TimeTrackingValue::getVarbitValue)
			.orElse(null);
	}

	static long birdHouseReadyAt(long observedAt)
	{
		return observedAt + BIRD_HOUSE_DURATION_SECONDS;
	}

	boolean hasRecordedCompost(FarmPatch patch)
	{
		return getRecordedCompost(patch) != null;
	}

	CompostState getRecordedCompost(FarmPatch patch)
	{
		if (!patch.supportsCompostReminder())
		{
			return null;
		}
		return configManager.getRSProfileConfiguration(
			TimeTrackingConfig.CONFIG_GROUP,
			patch.getTimeTrackingKey() + "." + TimeTrackingConfig.COMPOST,
			CompostState.class);
	}

	private boolean isLeaguesWorld()
	{
		EnumSet<WorldType> worldTypes = client.getWorldType();
		return worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN);
	}
}

